package org.slavicmyths.kalin;
import java.util.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.*;import net.minecraft.server.level.*;import net.minecraft.server.level.ServerBossEvent;import net.minecraft.world.BossEvent;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.Vec3;import org.slavicmyths.finist.*;import org.slavicmyths.skim.HeroCalls;
/** Exclusive server action clock, bounded owned army, collision checked straight charge. */
public final class KalinEntity extends FalconActor {
 private static final EntityDataAccessor<Boolean> SURRENDER=SynchedEntityData.defineId(KalinEntity.class,EntityDataSerializers.BOOLEAN);
 private static final EntityDataAccessor<Integer> PHASE=SynchedEntityData.defineId(KalinEntity.class,EntityDataSerializers.INT);
 public UUID owner,encounter,horse;public Vec3 center;public final Set<UUID> soldiers=new LinkedHashSet<>();private Vec3 charge;private final Set<UUID> hits=new HashSet<>();private LivingEntity committed;private int wave,step,waveCycle;private boolean dismounted,playerHit,parried,burst;private long finishAt;private int heroPressure;private final ServerBossEvent bar=new ServerBossEvent(net.minecraft.network.chat.Component.translatable("entity.slavicmyths.kalin_tsar"),BossEvent.BossBarColor.RED,BossEvent.BossBarOverlay.NOTCHED_20);
 /** Vanilla MAX_HEALTH attribute caps at1024; this fixed boss pool stays1800 without changing global attributes. */
 @Override public float getMaxHealth(){return 1800F;}
 public KalinEntity(EntityType<? extends KalinEntity> t,Level w){super(t,w);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(SURRENDER,false);b.define(PHASE,1);}
 public boolean surrendered(){return entityData.get(SURRENDER);}public int phase(){return entityData.get(PHASE);}public boolean mounted(){return getVehicle() instanceof WarHorse;}public Vec3 origin(){return center==null?position():center;}
 public boolean valid(){return encounter==null||level() instanceof ServerLevel w&&KalinEncounter.get(w).active(encounter);}
 public KalinEncounter.Entry entry(){return encounter==null||!(level() instanceof ServerLevel w)?null:KalinEncounter.get(w).entries.get(encounter);}
 public boolean mount(){if(!(level() instanceof ServerLevel w)||mounted()||dismounted)return false;var h=KalinContent.HORSE.get().create(w);h.commander=getUUID();h.moveTo(position());if(!w.addFreshEntity(h))return false;horse=h.getUUID();if(!startRiding(h,true)){h.discard();return false;}h.playSound(KalinContent.sound("horse_snort"),1,1);return true;}
 public void dismount(){if(dismounted)return;dismounted=true;var h=getVehicle();stopRiding();if(h instanceof WarHorse a){var at=KartausEncounter.ground((ServerLevel)level(),a.position().add(2,0,0),1.05,2.8);if(at==null)at=KartausEncounter.ground((ServerLevel)level(),a.position().add(-2,0,0),1.05,2.8);if(at!=null)setPos(at);a.getNavigation().stop();a.setDeltaMovement(Vec3.ZERO);a.begin(FalconAction.RECALL,45);a.exitAt=level().getGameTime()+45;a.playSound(KalinContent.sound("horse_rear"),1,1);}begin(FalconAction.MORPH,45);sound("horse_rear");}
 private void sound(String k){playSound(KalinContent.sound(k),.9F,1);}
 public boolean enemy(LivingEntity e){if(e==null||!e.isAlive())return false;if(e instanceof ServerPlayer p)return !p.isCreative()&&!p.isSpectator()&&(owner==null||p.getUUID().equals(owner));if(encounter==null&&org.slavicmyths.bogatyr.HeroThreats.availableHero(e))return true;var a=entry();return a!=null&&(e.getUUID().equals(a.heroA)||e.getUUID().equals(a.heroB))&&!KalinParty.recovering(e)&&!e.getPersistentData().getBoolean("KalinRetreated");}
 public LivingEntity partyTarget(Entity from){if(!(level() instanceof ServerLevel w))return null;var p=owner==null?null:w.getServer().getPlayerList().getPlayer(owner);var e=entry();if(e!=null){for(UUID id:List.of(e.heroA,e.heroB)){if(w.getEntity(id) instanceof LivingEntity h&&enemy(h)&&from.distanceToSqr(h)<16&&from.distanceToSqr(p==null?this:p)>9)return h;}}return enemy(p)?p:null;}
 public List<LivingEntity> targets(){var r=new ArrayList<LivingEntity>();var t=getTarget();if(enemy(t))r.add(t);if(level() instanceof ServerLevel w){var e=entry();if(e!=null){var p=w.getServer().getPlayerList().getPlayer(owner);if(enemy(p)&&!r.contains(p))r.add(p);for(UUID id:List.of(e.heroA,e.heroB))if(w.getEntity(id) instanceof LivingEntity h&&enemy(h)&&!r.contains(h))r.add(h);}}return r;}
 public static float diamondRaw(float net){return (float)((-.2+Math.sqrt(.04+.04*net))/.02);}
 public DamageSource source(String kind){var key=net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DAMAGE_TYPE,KalinContent.id("kalin_"+kind));return new DamageSource(level().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.DAMAGE_TYPE).getHolderOrThrow(key),this);}
 public void strike(LivingEntity e,float diamond){if(enemy(e)&&hasLineOfSight(e)){e.hurt(source(action()==FalconAction.DASH?"charge":action()==FalconAction.WAVE?"spin":action()==FalconAction.BANNER?"stomp":"sabre"),diamondRaw(diamond));e.knockback(.65,getX()-e.getX(),getZ()-e.getZ());}}
 public void summon(int mode){if(!(level() instanceof ServerLevel w)||surrendered())return;soldiers.removeIf(id->!(w.getEntity(id) instanceof KalinSoldier s)||!s.isAlive());int elites=mode==0?2+random.nextInt(2):mode==2?2:0;int commons=mode==1?6+random.nextInt(5):mode==2?6:0;
 int[][] points={{-26,-8},{26,-8},{-26,8},{26,8},{-8,26},{8,26}};for(int n=0;n<elites+commons&&soldiers.size()<14;n++){boolean elite=n<elites;for(int attempt=0;attempt<12;attempt++){int index=elite?4+attempt%2:(n+attempt)%4;var q=points[index];var proposed=origin().add(q[0]+(attempt/6)*2,0,q[1]+n%3*2);var at=KartausEncounter.ground(w,proposed,.85,2.3);if(at==null||targets().stream().anyMatch(t->t.position().distanceToSqr(at)<25)||w.getEntitiesOfClass(KalinSoldier.class,new net.minecraft.world.phys.AABB(at.add(-1,0,-1),at.add(1,3,1))).size()>0)continue;var s=(elite?KalinContent.ELITE:KalinContent.COMMON).get().create(w);s.commander=getUUID();s.moveTo(at);s.setTarget(getTarget());if(w.addFreshEntity(s)){soldiers.add(s.getUUID());s.playSound(KalinContent.sound(elite?"soldier_spawn_elite":"soldier_spawn_common"),.6F,1);}break;}}
 }
 private void cast(FalconAction a,String key,int cd){committed=getTarget();if(committed!=null)face(committed);begin(a);burst=false;if(mounted())((WarHorse)getVehicle()).begin(a);cooldown(key,cd);hits.clear();step=0;if(mounted()){var h=(WarHorse)getVehicle();h.setYRot(getYRot());h.yBodyRot=getYRot();}if(a==FalconAction.DASH){charge=heading();sound(mounted()?"horse_gallop_loop":"kalin_sabre_light");}if(a==FalconAction.BANNER)sound("horse_rear");if(a==FalconAction.SWORD)sound("kalin_sabre_heavy");if(a==FalconAction.WAVE)sound("kalin_spin_attack");if(a==FalconAction.GUARDS){sound("kalin_war_horn");sound("kalin_command_shout_fx");}}
 @Override public void tick(){super.tick();if(!(level() instanceof ServerLevel w))return;if(!isAlive()){bar.setVisible(false);bar.removeAllPlayers();return;}if(surrendered()){getNavigation().stop();setTarget(null);if(w.getGameTime()>=finishAt)discard();return;}if(!valid()){cleanup();discard();return;}
 if(tickCount==1&&encounter==null){center=position();mount();begin(FalconAction.INTRO,60);}if(owner!=null){var p=w.getServer().getPlayerList().getPlayer(owner);if(p==null||!p.isAlive()||p.serverLevel()!=w){var e=entry();if(e!=null)KalinEncounter.get(w).finish(w,e,false);else{cleanup();discard();}return;}if(tickCount%10==0)setTarget(p);}else if(tickCount%20==0)setTarget(org.slavicmyths.bogatyr.HeroThreats.debugOpponent(this,32));
 if(tickCount%20==0){bar.setProgress(getHealth()/1800);for(var p:w.players())if(!p.isSpectator()&&p.position().distanceToSqr(origin())<48*48)bar.addPlayer(p);else bar.removePlayer(p);soldiers.removeIf(id->!(w.getEntity(id) instanceof KalinSoldier s)||!s.isAlive());bar.setName(net.minecraft.network.chat.Component.translatable("gui.slavicmyths.kalin_army",soldiers.size()));}
 int phase=getHealth()<360?4:getHealth()<720?3:getHealth()<=1170?2:1;if(phase!=phase()){entityData.set(PHASE,phase);if(phase>=3){getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);sound("kalin_rage_burst");}}
 if(mounted()&&getHealth()<=1170){dismount();return;}if(getPersistentData().hasUUID("BogatyrTauntHero")&&w.getGameTime()<getPersistentData().getLong("BogatyrTauntUntil")&&w.getEntity(getPersistentData().getUUID("BogatyrTauntHero")) instanceof LivingEntity h&&enemy(h))setTarget(h);if(getPersistentData().hasUUID("AlyoshaTaunt")&&w.getGameTime()<getPersistentData().getLong("AlyoshaTauntUntil")&&w.getEntity(getPersistentData().getUUID("AlyoshaTaunt")) instanceof LivingEntity h&&enemy(h))setTarget(h);
 if(!enemy(getTarget())||getTarget().position().distanceToSqr(origin())>40*40){setTarget(null);getNavigation().stop();if(mounted())((WarHorse)getVehicle()).getNavigation().stop();return;}if(heroPressure>5&&tickCount%40==0){var h=partyTarget(this);if(enemy(h))setTarget(h);heroPressure=0;}
 if(action()!=FalconAction.IDLE){getNavigation().stop();int t=age();if((action()==FalconAction.SWORD&&frame(6))||(action()==FalconAction.INTERCEPT&&parried&&frame(8)))swing(net.minecraft.world.InteractionHand.MAIN_HAND);if(action()==FalconAction.SWORD&&frame(12)&&enemy(committed)&&cone(committed,mounted()?4.5:3.6,100))strike(committed,7);
 if(action()==FalconAction.WAVE&&(frame(15)||frame(26)||frame(37))){for(var target:targets())if(distanceToSqr(target)<(mounted()?36:25)&&hasLineOfSight(target)){strike(target,3); }{var mover=mounted()?getVehicle():this;var d=heading().scale(.12);if(mover.position().add(d).distanceToSqr(origin())<28*28&&w.noCollision(mover,mover.getBoundingBox().move(d)))mover.move(MoverType.SELF,d);if(mounted())setPos(mover.position().add(0,1.4,0));}}
 if(action()==FalconAction.INTERCEPT&&parried&&frame(14)&&enemy(committed)&&cone(committed,4,120))strike(committed,5);
 if(action()==FalconAction.GUARDS&&frame(22))summon(wave);
 if(action()==FalconAction.BANNER&&frame(25)){sound("horse_stomp");for(var target:targets())if(distanceToSqr(target)<16)strike(target,4);}
 if(action()==FalconAction.DASH&&t>=(burst?6:8)&&t<=(burst?12:21)&&charge!=null){var mover=mounted()?getVehicle():this;double speed=mounted()?(burst?.6:.9):.55;var d=charge.scale(speed);var next=mover.position().add(d);if(next.distanceToSqr(origin())>28*28||!w.hasChunkAt(net.minecraft.core.BlockPos.containing(next))||!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,net.minecraft.core.BlockPos.containing(next).below())||!w.noCollision(mover,mover.getBoundingBox().move(d))){begin(FalconAction.STAGGER,45);sound("horse_rear");return;}mover.move(MoverType.SELF,d);mover.setDeltaMovement(Vec3.ZERO);if(mounted()){setPos(mover.position().add(0,1.4,0));mover.setYRot(getYRot());((WarHorse)mover).yBodyRot=getYRot();}for(var target:targets())if(mover.getBoundingBox().inflate(.7).intersects(target.getBoundingBox())&&hits.add(target.getUUID()))strike(target,mounted()?6:5);}
 if(t>=duration()){begin(FalconAction.IDLE);if(mounted())((WarHorse)getVehicle()).begin(FalconAction.IDLE);cooldown("recovery",phase>=3?12:20);}return;}
 if(!ready("recovery"))return;if(tickCount%10!=0)return;face(getTarget());if(ready("army")&&soldiers.size()<14){wave=phase==1?0:phase==4?2:(waveCycle++%2==0?1:0);cast(FalconAction.GUARDS,"army",phase==1?900:phase==2?720:phase==3?540:420);return;}
 if(ready("parry")&&edge(getTarget())<4){parried=false;cast(FalconAction.INTERCEPT,"parry",200);return;}
 if(ready("charge")&&edge(getTarget())>5){cast(FalconAction.DASH,"charge",mounted()?160:240);return;}
 if(mounted()&&ready("burst")&&edge(getTarget())>3&&edge(getTarget())<7){cast(FalconAction.DASH,"burst",200);burst=true;begin(FalconAction.DASH,20);((WarHorse)getVehicle()).begin(FalconAction.DASH,20);return;}
 if(mounted()&&ready("stomp")&&edge(getTarget())<2){cast(FalconAction.BANNER,"stomp",240);return;}
 if(ready("spin")&&edge(getTarget())<5){cast(FalconAction.WAVE,"spin",300);return;}if(ready("sabre")&&edge(getTarget())<3.6){cast(FalconAction.SWORD,"sabre",52);return;}var mover=mounted()?(WarHorse)getVehicle():this;if(tickCount%10==0){var at=getTarget().position();var offset=at.subtract(origin()).multiply(1,0,1);if(offset.lengthSqr()>27*27)at=origin().add(offset.normalize().scale(24));mover.getNavigation().moveTo(at.x,origin().y,at.z,1);}}
 @Override public boolean hurt(DamageSource s,float d){if(surrendered())return false;if(s.getEntity() instanceof KalinSoldier||s.getEntity() instanceof WarHorse)return false;if(action()==FalconAction.INTERCEPT&&age()>=2&&age()<=8&&!parried&&s.getDirectEntity() instanceof LivingEntity attacker&&enemy(attacker)&&(KalinParty.owner(attacker)!=null||attacker.getMainHandItem().is(net.minecraft.tags.ItemTags.SWORDS)||attacker.getMainHandItem().is(net.minecraft.tags.ItemTags.AXES))&&cone(attacker,4,120)&&!s.is(net.minecraft.tags.DamageTypeTags.IS_PROJECTILE)&&!s.is(net.minecraft.tags.DamageTypeTags.BYPASSES_INVULNERABILITY)){parried=true;committed=attacker;sound("kalin_parry");return false;}return super.hurt(s,d);}
 public void damageReceived(DamageSource s){if(s.getEntity() instanceof ServerPlayer p&&owner!=null&&owner.equals(p.getUUID())&&!p.isCreative())playerHit=true;else if(s.getEntity() instanceof Mob m&&enemy(m))heroPressure++;}
 public void surrender(DamageSource source){if(surrendered())return;setHealth(1);entityData.set(SURRENDER,true);finishAt=level().getGameTime()+100;begin(FalconAction.DEATH,100);setTarget(null);sound("kalin_kneel_surrender");cleanup();if(level() instanceof ServerLevel w){var e=entry();if(e!=null)KalinEncounter.get(w).finish(w,e,playerHit&&!source.is(net.minecraft.world.damagesource.DamageTypes.GENERIC_KILL),org.slavicmyths.progression.AdvancementMilestones.combatDeath(source));}}
 @Override protected net.minecraft.world.InteractionResult mobInteract(net.minecraft.world.entity.player.Player p,net.minecraft.world.InteractionHand hand){if(!surrendered())return super.mobInteract(p,hand);if(p instanceof ServerPlayer s)s.sendSystemMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths.kalin_surrender"));return net.minecraft.world.InteractionResult.sidedSuccess(level().isClientSide);}
 @Override public void onRemovedFromLevel(){bar.setVisible(false);bar.removeAllPlayers();super.onRemovedFromLevel();}
 public void cleanup(){bar.removeAllPlayers();if(!(level() instanceof ServerLevel w))return;for(var id:new ArrayList<>(soldiers)){var e=w.getEntity(id);if(e!=null)e.discard();}soldiers.clear();stopRiding();if(horse!=null&&w.getEntity(horse) instanceof WarHorse h)h.discard();}
 @Override protected void playStepSound(net.minecraft.core.BlockPos p,net.minecraft.world.level.block.state.BlockState state){if(!level().isClientSide&&!mounted())sound("kalin_step_heavy_"+(random.nextBoolean()?"01":"02"));}
 @Override protected net.minecraft.sounds.SoundEvent getHurtSound(DamageSource s){return net.minecraft.sounds.SoundEvents.IRON_GOLEM_HURT;}
 @Override protected void dropAllDeathLoot(ServerLevel w,DamageSource s){}@Override protected void dropExperience(Entity e){}
 @Override public void addAdditionalSaveData(CompoundTag n){super.addAdditionalSaveData(n);if(owner!=null)n.putUUID("KalinOwner",owner);if(encounter!=null)n.putUUID("KalinEncounter",encounter);if(horse!=null)n.putUUID("KalinHorse",horse);n.putLong("KalinCenter",net.minecraft.core.BlockPos.containing(origin()).asLong());n.putBoolean("KalinDismounted",dismounted);n.putBoolean("KalinSurrendered",surrendered());n.putLong("KalinFinishAt",finishAt);n.putBoolean("KalinPlayerHit",playerHit);var l=new net.minecraft.nbt.ListTag();soldiers.forEach(id->l.add(net.minecraft.nbt.StringTag.valueOf(id.toString())));n.put("KalinSoldiers",l);}
 @Override public void readAdditionalSaveData(CompoundTag n){super.readAdditionalSaveData(n);owner=n.hasUUID("KalinOwner")?n.getUUID("KalinOwner"):null;encounter=n.hasUUID("KalinEncounter")?n.getUUID("KalinEncounter"):null;horse=n.hasUUID("KalinHorse")?n.getUUID("KalinHorse"):null;center=Vec3.atBottomCenterOf(net.minecraft.core.BlockPos.of(n.getLong("KalinCenter")));dismounted=n.getBoolean("KalinDismounted");entityData.set(SURRENDER,n.getBoolean("KalinSurrendered"));finishAt=n.getLong("KalinFinishAt");playerHit=n.getBoolean("KalinPlayerHit");soldiers.clear();for(var t:n.getList("KalinSoldiers",net.minecraft.nbt.Tag.TAG_STRING))soldiers.add(UUID.fromString(t.getAsString()));}
}
